  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: 500, r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// --- New Tests for Issue #1 (Brick Bounces) ---

const mockCtx = {
  fillStyle: '',
  fillRect: () => {},
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
  font: '',
  fillText: () => {},
};

test('brick bounce: top face', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 50, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  // Ball hitting from top: vy should flip to UP (negative), x should be inside
  state.ball = { x: 125, y: 95, r: 7, vx: 100, vy: 200 }; // Moving DOWN

  frame(mockCtx, state);

  assert.equal(Math.sign(state.ball.vy), UP, 'vy should flip to UP');
  assert.equal(Math.sign(state.ball.vx), RIGHT, 'vx should remain RIGHT');
  assert.ok(state.ball.y < brick.y, 'ball should be pushed out to top');
  assert.equal(brick.alive, false);
});

test('brick bounce: bottom face', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 50, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  state.ball = { x: 125, y: 125, r: 7, vx: 100, vy: -200 }; // Moving UP

  frame(mockCtx, state);

  assert.equal(Math.sign(state.ball.vy), DOWN, 'vy should flip to DOWN');
  assert.equal(Math.sign(state.ball.vx), RIGHT, 'vx should remain RIGHT');
  assert.ok(state.ball.y > brick.y + brick.h, 'ball should be pushed out to bottom');
  assert.equal(brick.alive, false);
});

test('brick bounce: left face', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 50, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  state.ball = { x: 95, y: 110, r: 7, vx: 200, vy: 100 }; // Moving RIGHT

  frame(mockCtx, state);

  assert.equal(Math.sign(state.ball.vx), LEFT, 'vx should flip to LEFT');
  assert.equal(Math.sign(state.ball.vy), DOWN, 'vy should remain DOWN');
  assert.ok(state.ball.x < brick.x, 'ball should be pushed out to left');
  assert.equal(brick.alive, false);
});

test('brick bounce: right face', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 50, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  state.ball = { x: 155, y: 110, r: 7, vx: -200, vy: 100 }; // Moving LEFT

  frame(mockCtx, state);

  assert.equal(Math.sign(state.ball.vx), RIGHT, 'vx should flip to RIGHT');
  assert.equal(Math.sign(state.ball.vy), DOWN, 'vy should remain DOWN');
  assert.ok(state.ball.x > brick.x + brick.w, 'ball should be pushed out to right');
  assert.equal(brick.alive, false);
});

test('brick bounce: corner (diagonal)', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 50, h: 20, alive: true, points: 10 };
  state.bricks = [brick];
  // Hit exactly on a corner, equal penetration on x and y
  // Ball center at 93, 93. Brick top-left is 100, 100.
  // Pen x: 100 - (93 + 7) = 0? No, ball.x+r = 100.
  // Let's make it clearly overlapping.
  state.ball = { x: 98, y: 98, r: 7, vx: 200, vy: 200 };

  frame(mockCtx, state);

  assert.equal(Math.sign(state.ball.vx), LEFT, 'vx should flip to LEFT');
  assert.equal(Math.sign(state.ball.vy), UP, 'vy should flip to UP');
  assert.equal(brick.alive, false);
});

test('brick bounce: tunnelling prevention', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 50, h: 20, alive: true, points: 10 };
  state.bricks = [brick];

  // Ball is at y=80, vx=0, vy=500. dt=0.05 => dy = 25.
  // Next pos y=105. The brick is at 100-120.
  // The ball diameter is 14. It should not tunnel through a 20px brick.
  // But if vy is very high, it might.
  state.ball = { x: 125, y: 80, r: 7, vx: 0, vy: 1000 }; 

  // In the current architecture, tunnelling is handled in step()? 
  // No, step() just adds velocity. frame() checks collides().
  // If ball jumps from 80 to 130, it misses the brick (100-120).
  // We need to implement sweep in step() or handle it here.

  // For now, let's see if it fails.
  step(state, 0.05); // ball.y = 80 + 50 = 130.
  frame(mockCtx, state);

  assert.equal(brick.alive, false, 'ball should not tunnel through brick');
});

