// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Does NOT handle bricks: that responsibility still
// lives in the render loop `frame()` (debt #2).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  const oldX = ball.x;
  const oldY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    // The rebound angle depends on where the paddle was hit.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0; // touching the paddle resets the combo
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

// Helper for tunnelling detection: checks if the ball passed through a brick between two positions.
function sweepBrick(ball, oldX, oldY, brick) {
  if (!brick.alive) return false;

  // A simple way to handle tunnelling is to check if the ball's path intersects the brick.
  // For a brick breaker, checking if the ball was on one side and now is on the other 
  // while its x-range overlaps the brick is usually enough.

  // The ball is a circle, so we check the bounding box of the movement.
  const minX = Math.min(oldX, ball.x) - ball.r;
  const maxX = Math.max(oldX, ball.x) + ball.r;
  const minY = Math.min(oldY, ball.y) - ball.r;
  const maxY = Math.max(oldY, ball.y) + ball.r;

  return (
    maxX > brick.x &&
    minX < brick.x + brick.w &&
    maxY > brick.y &&
    minY < brick.y + brick.h
  );
}

