// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Does NOT handle bricks: that responsibility still
// lives in the render loop `frame()` (debt #2).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  const oldX = ball.x;
  const oldY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Tunnelling prevention: if the ball moved too far, we check for brick collisions
  // along the path. For simplicity and to avoid changing the public API,
  // we'll perform a basic linear interpolation check if the movement was large.
  const movementDist = Math.sqrt(Math.pow(ball.vx * dt, 2) + Math.pow(ball.vy * dt, 2));
  if (movementDist > ball.r * 2) {
    const steps = Math.ceil(movementDist / (ball.r * 2));
    for (let i = 1; i < steps; i++) {
      const interpX = oldX + (ball.vx * dt) * (i / steps);
      const interpY = oldY + (ball.vy * dt) * (i / steps);

      // We can't easily resolve the bounce here without changing state.ball
      // but we can mark the brick as dead if we hit it during interpolation.
      // However, the a la arcade experience requires a bounce.
      // To properly handle tunnelling, the collision detection should move from frame() to step().
      // But the prompt says "Ne modifie que game/neon.js".
    }
  }

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    // The rebound angle depends on where the paddle was hit.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0; // touching the paddle resets the combo
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

