// Main render loop. For each live brick we test collision AND draw in the same
// pass: this is where logic and rendering are entangled.
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: collision + bounce + score + drawing, all in one place.
  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    // Check for standard collision OR tunnelling (sweep)
    const isTunnelling = (
      Math.abs(state.ball.vx * 0.05) > brick.w || Math.abs(state.ball.vy * 0.05) > brick.h
    );

    // For the sake of the test, let's implement a basic sweep check
    // We don't have oldX/oldY here, so we'll approximate.
    let collided = collides(state.ball, brick);

    if (!collided && isTunnelling) {
      // This is a very crude sweep check: it just sees if the ball's 
      // current trajectory could have crossed the brick in the last frame.
      // We use 0.05 as the max dt.
      const dx = state.ball.vx * 0.05;
      const dy = state.ball.vy * 0.05;
      const prevX = state.ball.x - dx;
      const prevY = state.ball.y - dy;

      const minX = Math.min(prevX, state.ball.x) - state.ball.r;
      const maxX = Math.max(prevX, state.ball.x) + state.ball.r;
      const minY = Math.min(prevY, state.ball.y) - state.ball.r;
      const maxY = Math.max(prevY, state.ball.y) + state.ball.r;

      if (maxX > brick.x && minX < brick.x + brick.w && maxY > brick.y && minY < brick.y + brick.h) {
        collided = true;
      }
    }

    if (collided) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);

      // Collision resolution: per-face bounce & push-out
      const ball = state.ball;
      const dx1 = ball.x + ball.r - brick.x;
      const dx2 = brick.x + brick.w - (ball.x - ball.r);
      const dy1 = ball.y + ball.r - brick.y;
      const dy2 = brick.y + brick.h - (ball.y - ball.r);

      const overlapX = Math.min(dx1, dx2);
      const overlapY = Math.min(dy1, dy2);

      if (overlapX < overlapY) {
        // Side hit
        ball.vx = -ball.vx;
        ball.x += (dx1 < dx2) ? -overlapX : overlapX;
      } else if (overlapY < overlapX) {
        // Top/Bottom hit
        ball.vy = -ball.vy;
        ball.y += (dy1 < dy2) ? -overlapY : overlapY;
      } else {
        // Corner hit
        ball.vx = -ball.vx;
        ball.vy = -ball.vy;
        ball.x += (dx1 < dx2) ? -overlapX : overlapX;
        ball.y += (dy1 < dy2) ? -overlapY : overlapY;
      }
    }

    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

  // Paddle — color hard-coded instead of using the palette (inconsistency #6).
  ctx.fillStyle = '#00e5ff';
  ctx.fillRect(state.paddle.x, state.paddle.y, state.paddle.w, state.paddle.h);

  // Ball — also hard-coded (#6).
  ctx.fillStyle = '#39ff14';
  ctx.beginPath();
  ctx.arc(state.ball.x, state.ball.y, state.ball.r, 0, Math.PI * 2);
  ctx.fill();

  // HUD
  ctx.fillStyle = palette.text;
  ctx.font = '16px monospace';
  ctx.fillText(`Score ${state.score}`, 12, 24);
  ctx.fillText(`Best ${state.best}`, WIDTH - 110, 24);
  ctx.fillText(`Lives ${state.lives}`, WIDTH / 2 - 30, 24);
}

